    stem: "在音乐的理论中，有所谓的“音乐的语言”；在语文形式美的理论中，应该________有所谓的“语言的音乐”。________音乐和语言不是一回事，________二者之间有一个共同点：音乐和语言都是靠声音来表现的。\n依次填入画横线部分最恰当的一项是：",
