    analysis: "第一空，横线处搭配“这类治理”行为，根据前文“对破旧报亭进行维修、粉饰”“拆除私自搭建的各类棚架”可知，这类治理已经付诸具体的行动。A项“纸上谈兵”比喻空谈理论，不能解决实际问题，侧重指没有具体行动，与文意不符，排除；根据后文“制造更多问题”可知，横线处应体现出一种不恰当的做法，B项“公事公办”指公事按公事的原则办，不讲私人情面，是一种积极正确的做法，与文段的语境不符，排除。\n第二空，用来形容“动不动就把报亭拆除”之后的结果，根据前文“对报刊亭开展过整治”可知，拆除只是众多“整治”方法中的一个非常简单、粗暴、过分的方法，D项“过犹不及”指事情做得过头，就跟做得不够一样，都是不合适的，符合文意，当选。C项“事倍功半”形容做事的方法费力大，收效小，文段中明确表示“动不动就把报刊亭拆除”是一种比较单一的方法，无法体现出“事倍”，排除。\n故正确答案为D。\n【文段出处】《应多扶持报刊亭这个“文化载体”》",
