    stem: "（1）十年燕园的________，从法学学士到经济博士，李克强有着深厚的人文________和开阔的国际视野。\n（2）《旧制度与大革命》探讨的是法国大革命，但社会动荡并未带来革命党预期的结果，无论是统治者还是民众，最后都被相互间的怒火所________。\n依次填入画横线部分最恰当的一项是：",
