    stem: "地球是一个不规则的椭圆体，想要把球体________在平面上，必须要经过投影。所谓投影，就是将地球椭圆上的点________到地图平面上的点的方法。而经过投影呈现出的地图，最终都会不同程度地出现________的现象。\n填入画横线部分最恰当的一项是：",
