    stem: "人们把随地吐痰、踩踏草坪归咎于道德问题，其实这些举动也透露出对自然的不敬畏，对环境的_____。正是由于这些诸多举手投足的小事，让我们共同的家园变得_____。\n依次填入画横线部分最恰当的一项是：",
