    analysis: "第一空，“对自然的不敬畏”与“对环境的\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0”是相同句式构成的并列，横线处对应“不敬畏”，且搭配“环境”，表示对环境的不好态度。B项“破坏”即损坏，是不良行为，而非态度，不符合语境，排除；D项“亵渎”指轻慢、不庄重、不尊敬，常修饰“爱情、神灵、圣人”，与“环境”搭配不当，排除。\n第二空，由“随地吐痰、踩踏草坪”“不敬畏”等，可知横线处所填词语色彩消极。A项“今非昔比”意为现在不是过去能比得上的，通常指现在比过去好，体现不出消极色彩，排除。C项“面目全非”指样子完全不同了，形容改变得不成样子，多用作消极色彩，符合语境，当选。\n故正确答案为C。\n【文段出处】《敬畏自然》",
