    stem: "秦、晋第一次韩原大战的旌旗战尘遮蔽了赤日，将如注如流的碧血________这片干旱的黄土。那时，大获全胜的秦穆公与当了俘虏的晋惠公没有料到，五百多年之后，生于斯地长于斯地的一个史官会用饱蘸着恋乡之情的笔墨，________地记载下那场________的厮杀，记载下他们的荣耀与耻辱。\n依次填入画横线部分最恰当的一项是：",
