    analysis: "本题可从第二空入手，“对此”指代的是前文的担忧，所以后文应体现出不用担忧之意，A项“杞人忧天”比喻毫无必要的忧虑和担心，符合文意，保留；D项“庸人自扰”泛指本来没有问题而自己瞎着急或自找麻烦，符合文意，保留；B项“瞻前顾后”多形容顾虑过多，犹豫不决、C项“左右为难”形容无论怎样做都有难处，均无担忧之意，与文意不符，排除。\n\xa0第一空，形容机器人在各个行业的发展现状。A项“大显身手”指充分显露自己的本领，体现如今机器人发展较好，也符合后文人民的担忧，符合文意，当选；D项“一枝独秀”形容在同类事物中最为突出，最为优秀，程度过重，排除。\n故正确答案为A。\n【文段出处】《机器人时代到来\xa0你会下岗吗》",
