    stem: "有人说，刘慈欣仅凭一己之力，就使中国的科幻小说________于世界先进水平之列。这对于作家本人来说，________是崇高的盛誉，但若从另一方面解读，其中何尝不隐含着十分的无奈。刘慈欣和《三体》的一花独放、单峰耸峙，________出的是科幻小说界的整体低迷。就整体而言，无论是科幻小说的创作、出版、阅读和传播，还是改编拍摄成影视作品等________艺术形式，中国跟世界先进水平都存在着巨大的差距。\n依次填入画横线部分最恰当的是：",
