    answer: "C",
    analysis: "第一空，根据后文“用锣鼓和鞭炮的声音来驱赶‘恶狗’”可知，实行该措施并没有成效。C项“力所能及”指自己的能力所能办到的，符合文意，保留。A项“行之有效”指实行起来有成效，D项“恰如其分”是指办事或说话正合分寸，均与文意相悖，排除；B项“大张旗鼓”指声势和规模很大，也比喻公开，用法通常为“大张旗鼓地做某事”，不能用来修饰“措施”，排除。\n第二空，代入验证，横线处所填成语用来形容“用锣鼓和鞭炮的声音来驱赶‘恶狗’”这一行为让现代人不解。C项“匪夷所思”指事物怪异或人的言、行离奇，不是一般人按照常理所能想象的，符合文意，当选。\n\n故正确答案为C。\n\n【文段出处】北京晚报\xa0《为日全食上书国务院\xa0天文学家澄清日食“绯闻”》",
