    analysis: "第一空，文段论述的是人民币国际化并逐步发展已成为趋势，A项“势如破竹”指形势就像劈竹子，形容节节胜利，毫无阻碍、B项“势不可挡”比喻来势迅猛，不可抵挡，二者均可表达已成为趋势之意，符合文意，保留。C项“势在必行”强调某件事必须去做，而文段仅是从客观角度指人民币有成为储备货币的趋势，并非强调逐步发展为储备货币的必须性，不符合文意，排除。D项“势如累卵”比喻形势非常危急，不符合文意，排除。\n第二空，要与“长期向好的”搭配，A项“态势”、B项“趋势”均可保留。\n第三空，搭配“提供”，可知是由外力给予的。B项“动力”体现了现实情况对各国央行选择人民币产生的推动力量，且“提供动力”为常见搭配，符合文意，当选。A项“动机”是内在心理过程或内部动力，与“提供”搭配不当，排除。\n故正确答案为B。\n【文段出处】《外国央行抢做人民币生意\xa0其成储备货币势不可挡》",
