    stem: "法治和礼治发生在两种不同的社会________中。这里所谓的礼治也许就是通常所谓的人治，但是礼治一词不会像人治一词那样容易引起________，以致有人觉得社会秩序是可以由个人好恶来维持的了。\n依次填入划横线部分最恰当的一项是：",
