    stem: "筹算应用了大约两千年，对中国古代数学的发展功不可没。但筹算有个严重缺点，就是运算过程不保留。元朝数学家朱世杰能用筹算解四元高次方程，其数学水平居世界领先地位，但是他的方法难懂，运算过程又不能保留，因而________。中国古代数学不能发展为现代数学，筹算方法的________是个重要原因。\n依次填入画横线部分最恰当的一项是：",
