    stem: "在量子理论产生之前，人类在宏观世界里从未观测到任何负能量的物质。把真空的能量定为零的经典物理学，无法________一种比真空具有更少能量的物质。而在量子理论中，真空不再是________，每时每刻都有大量的虚粒子对（一种永远不能直接检测到，但其存在确实具有可测量效应的粒子）产生和湮灭。\n依次填入画横线部分最恰当的一项是：",
