    analysis: "本题可从第二空入手，填入的词与前句“尊重”相对应，且搭配“历史”，D项“敬畏历史”为固定搭配，当选。A项“畏忌”、C项“畏惧”均表示害怕的意思，与“历史”搭配不当，排除。B项“敬重”通常形容下级对上级或晚辈对长辈的恭敬和尊重，与“历史”搭配不当，排除。\n第一、三空代入验证，均符合文意。\n故正确答案为D。\n【成语拓展】\n捕风捉影：风和影子都是抓不住的，比喻说话做事丝毫没有事实根据。\n自以为是：认为自己的看法和做法都正确，不接受别人的意见，形容骄傲自大。\n空穴来风：比喻消息和传说不是完全没有原因的，现多用来指消息和传说毫无根据。\n【文段出处】人民日报\xa0\xa0《普及历史知识首先应尊重历史真实》",
