    stem: "社会的和谐，是以人与人之间的爱即仁爱为______基础的，也是以执政者怀抱民本思想执政为民，惠及民生为基础的。可以说，正是传统仁爱思想和民本思想的有力_______，才确保了中华民族5000年历史的______。\n依次填入划横线处最恰当的一项是：",
