    analysis: "本题从第三空入手。根据“中华民族5000\xa0年历史的\xb7\xb7\xb7\xb7\xb7\xb7”可知，横线处所填词语强调历史一直延续，B项“绵延不绝”指连接不断，一直延续，符合文意，保留。A项“革故鼎新”指去除旧的，建立新的，强调“故”“新”两方面，C项“历久弥新”指经历长久的时间而更加鲜活，更加有活力，更显价值，这两个成语中强调的“新”均未在文段中体现，排除；D项“山高水长”指人节操高尚、影响深远，与“历史”搭配不当，排除。\xa0\n第一空，代入验证，“以仁爱为情感基础”搭配恰当，且符合文意，B项保留。\xa0\n第二空，代入验证，B项“维系”中的“系”即“联系”，与后文“中华民族5000年历史”形成对应，符合文意，当选。\xa0\n故正确答案为B。\xa0\n【成语积累】革故鼎新：指去除旧的，建立新的，多指改朝换代或重大变革等。\n山高水长：像山一样高耸，如水一般长流，原比喻人的风范或声誉像高山一样永远存在，后比喻恩德深厚。\n【文段出处】光明日报《中华传统美德的时代价值》",
