    answer: "A",
    analysis: "第一空，根据“以量取胜”“孤立的单个数据几乎没有商品价值”可知，横线处所填词语应该表示记录主体不重视、不关注数据产权。C项“遗忘”表示忘记，文段并未强调主动忘记数据产权，排除；D项“遗弃”表示抛弃，强调主观上的放弃，文段未体现主动放弃数据产权，排除。\xa0\n第二空，A项“集腋成裘”比喻积少成多，B项“积少成多”指只要不断积累，就会从少变多，二者均符合文意，保留。\xa0\n第三空，根据“须借助复杂的分析算式与大功率计算机”可知，横线处所填词语强调普通人和小公司没有条件去处理大数据。A项“难以问津”表示很难去探求途径或尝试，符合文意，当选。B项“难以为继”指之前一直在做的事情难以继续下去，文段中小公司和普通人根本没有开始做，排除。\xa0\n故正确答案为A。\xa0\n【成语积累】望洋兴叹：字面意思是在伟大的事物面前感叹自己的渺小，现多比喻做事时因力不胜任或没有条件而感到无可奈何。\n望而却步：指远远望见了就吓得后退，不敢前行。\n【文段出处】澎湃新闻《大数据卖的就是隐私》",
