    stem: "①西欧的政治与社会制度，在刚有文字记载的远古时代，即已表现出原始的民主________。\n②如果我们只________于现实生活之内，则我们显然无法看清人生的全部，找不到自己的生命方向。\n填入划横线部分最恰当的一项是：",
