    stem: "一项研究结果___________了在梦中各种感官体验出现的频率，结果显示视觉体验居第一，听觉体验居第二，而触觉、嗅觉和味觉体验的出现频率相当低。视觉和听觉处理与大脑的关系要密切得多，多达三分之二的大脑皮层以某种方式参与视觉。因此，视觉如此频繁地在梦中出现，___________。而嗅觉等几乎与大脑皮层无关。与其他感觉不同，嗅觉直接连接进入记忆和情感系统，这就是为什么某种气味能如此清晰地唤起某个记忆。\n依次填入划横线部分最恰当的一项是：",
