    stem: "一位思想家，不管多么伟大，本质上都只属于他所生活的那个年代。这一点，古今中外________。所以，今天对孔子的某些思想予以扬弃，是一件自然而然的事，完全用不着________，也用不着大张旗鼓地批判。\n依次填入画横线部分最恰当的一项是：",
