    analysis: "第一空，根据横线前文“本质上都只属于他所生活的那个年代”可知，古今中外，不论什么时候，这样的观点都属于这个范围之内，谁都不能例外，C项“概莫能外”指一概不能除外，指都在所指范围之内，符合文意，保留；A项“如出一辙”比喻两件事情非常相似，B项“大同小异”指大体相同，略有差异，D项“一视同仁”表示对人同样看待，不分厚薄，三项均不符合文意，排除。\n第二空，代入验证，根据“是一件自然而然的事”可知，C项“大惊小怪”形容不用过分惊讶，放入文段符合语境，当选。\n故正确答案为C。",
